<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../lib/DocsAccessService.php';Auth::requireLogin();try{$doc=DocsAccessService::requireDoc((int)($_GET['id']??0));if(!$doc['attachment_path'])throw new RuntimeException('missing');$root=realpath(__DIR__.'/..');$base=realpath($root.'/uploads/docs');$file=realpath($root.'/'.ltrim($doc['attachment_path'],'/'));if(!$base||!$file||!str_starts_with(strtolower($file),strtolower($base.DIRECTORY_SEPARATOR))||!is_file($file))throw new RuntimeException('missing');Auth::log((int)Auth::user()['id'],'docs_attachment_downloaded','docs_articles',(int)$doc['id']);header('Content-Type: '.($doc['attachment_mime']?:'application/octet-stream'));header('Content-Length: '.filesize($file));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($doc['attachment_name']?:basename($file)));header('X-Content-Type-Options: nosniff');readfile($file);exit;}catch(Throwable $e){error_log('Doc download: '.$e->getMessage());http_response_code(404);exit('فایل در دسترس نیست.');}
